class Solution { public:
    long long minimumReplacement(vector<int>& nums) {
        long long ans=0,limit=nums.back();
        for(int i=(int)nums.size()-2;i>=0;--i){
            long long pieces=(nums[i]+limit-1)/limit;
            ans+=pieces-1;limit=nums[i]/pieces;
        }
        return ans;
    }
};
